(()=>{"use strict";const money=n=>typeof window<"u"&&window.CMI18n?window.CMI18n.currency(Number(n),"USD",{maximumFractionDigits:2,minimumFractionDigits:2}):"$"+Number(n).toLocaleString("en-US",{maximumFractionDigits:2,minimumFractionDigits:2}),num=n=>Number(n).toLocaleString(typeof window<"u"&&window.CMI18n?window.CMI18n.formatLocale:"en-US",{maximumFractionDigits:2}),$=id=>document.getElementById(id);function get(){const v={};return document.querySelectorAll("input").forEach(e=>{v[e.id]=parseFloat(e.value)||0}),v}function calc(v){const raw=v.calls*v.wh/1e3,energy=v.calls*v.wh*v.pue/1e3,kg=energy*v.grid/1e3;return{raw,energy,kg,perCall:v.wh*v.pue*v.grid/1e3,per1000:v.wh*v.pue*v.grid}}function render(){const v=get();if(!(v.calls>0&&v.wh>=0&&v.grid>=0&&v.pue>=0)){$("result").textContent="\u2014",$("chipA").textContent="\u2014",$("chipB").textContent="\u2014",$("chipC").textContent="\u2014",$("breakRows").innerHTML="",$("bars").innerHTML="",$("cumRows").innerHTML="";const vd2=$("verdict");vd2.className="verdict warn",$("verdictText").textContent="Enter a call count above zero, with energy, grid intensity, and PUE at zero or above, to see the estimate.",window.__summary="";return}const r=calc(v);$("result").textContent=num(r.kg)+" kg CO\u2082e",$("chipA").textContent=num(r.energy)+" kWh",$("chipB").textContent=num(r.perCall)+" g CO\u2082e",$("chipC").textContent=num(r.per1000)+" g CO\u2082e";const row=(l,val)=>"<tr><td>"+l+"</td><td class='num'>"+val+"</td></tr>";$("breakRows").innerHTML=row("Inference energy (before PUE)",num(r.raw)+" kWh")+row("Facility overhead (PUE)",num(r.energy-r.raw)+" kWh")+row("Total energy",num(r.energy)+" kWh")+row("Grid intensity used",num(v.grid)+" gCO\u2082e/kWh")+row("Total emissions",num(r.kg)+" kg CO\u2082e"),$("bars").innerHTML=barRow("Inference energy",num(r.raw)+" kWh",r.raw,Math.max(r.raw,r.energy,1),"")+barRow("Total incl. PUE",num(r.energy)+" kWh",r.energy,Math.max(r.raw,r.energy,1),"new"),$("cumRows").innerHTML=row("10,000 calls",num(1e4*v.wh*v.pue*v.grid/1e3/1e3)+" kg CO\u2082e")+row("50,000 calls",num(5e4*v.wh*v.pue*v.grid/1e3/1e3)+" kg CO\u2082e")+row("100,000 calls",num(1e5*v.wh*v.pue*v.grid/1e3/1e3)+" kg CO\u2082e")+row("200,000 calls",num(2e5*v.wh*v.pue*v.grid/1e3/1e3)+" kg CO\u2082e");const vd=$("verdict");r.kg<=0?(vd.className="verdict",$("verdictText").textContent="Zero on these inputs: at least one of energy per call, grid intensity, or calls is zero, so the estimate is zero."):v.pue<1?(vd.className="verdict warn",$("verdictText").textContent="PUE below 1 is not physically meaningful for a facility total (it would imply less energy than the inference itself). Use 1.0 for no overhead, or a value above 1."):(vd.className="verdict",$("verdictText").textContent="On your assumptions, this scenario uses "+num(r.energy)+" kWh and emits "+num(r.kg)+" kg CO\u2082e. Treat it as a scenario estimate: the result moves in direct proportion to energy per call and grid intensity, which are the two inputs most worth verifying."),window.__summary="AI carbon estimate: "+num(r.energy)+" kWh, "+num(r.kg)+" kg CO2e for "+num(v.calls)+" calls at "+num(v.wh)+" Wh/call, PUE "+num(v.pue)+", grid "+num(v.grid)+" gCO2e/kWh."}function barRow(l,disp,val,maxV,cls){const p=maxV>0?Math.max(0,Math.min(100,val/maxV*100)):0;return"<div class='bar-row'><label><span>"+l+"</span><span>"+disp+"</span></label><div class='bar'><i class='"+cls+"' style='width:"+p+"%'></i></div></div>"}document.querySelectorAll("input").forEach(e=>e.addEventListener("input",render)),render()})();
